import math


CART_FORCE_LIMIT_NEWTONS = 4.0


INITIAL_REF_TRACK_CENTER_X = 50.0


def normalize_angle(theta):
    return math.atan2(math.sin(theta), math.cos(theta))


def build_agent(sandbox):
    # Return the cart body for control
    return sandbox.get_cart_body()


def agent_action(sandbox, agent_body, step_count):
    theta = normalize_angle(sandbox.get_pole_angle())
    omega = sandbox.get_pole_angular_velocity()
    x, v = sandbox.get_cart_position(), sandbox.get_cart_velocity()
    target_x = INITIAL_REF_TRACK_CENTER_X

    # Check if pole is near horizontal (angle > 1.5 radians)
    if abs(theta) > 1.5:
        # Reduce force contribution to prevent rapid cart movement
        force = -5 * theta  # Only adjust theta term
    else:
        # Check if near target to limit force
        if abs(x - target_x) < 0.15:
            force = -5 * theta - 5 * omega
        else:
            # Balance pole and position
            force = -5 * theta - 5 * omega - 2.0 * (x - target_x) - 0.5 * v

    # Clamp to actuator limit
    lim = CART_FORCE_LIMIT_NEWTONS
    force = max(-lim, min(lim, force))
    sandbox.apply_cart_force(force)
